(function () {
  'use strict';
  const C = window.SIGE_CORE;
  const KEY = 'sige-desk-demo-v1';
  const TOUR_KEY = 'sige-desk-tours-v1';
  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
  const esc = value => String(value ?? '').replace(/[&<>'"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' })[char]);
  const slug = value => String(value).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
  const initials = name => String(name).split(' ').slice(0, 2).map(v => v[0]).join('').toUpperCase();
  const icon = name => ({ dashboard:'▦',tickets:'◫','new-ticket':'+',triage:'⌁',execution:'▶',validation:'✓',notifications:'●',reports:'▥',clients:'◇',campaigns:'◎',types:'≡',sla:'◷',users:'♙' }[name] || '•');
  let data = load();
  let ui = { mobile: false, search: '', status: '', client: '', ticketView: 'kanban', page: 1, tab: 'overview', modal: null, tour: null, tourOffered: false, loginError: '', fieldErrors: {} };
  const TOUR_STEPS = {
    'Cliente': [
      { route:'dashboard', selector:'.page-head', title:'Seu painel', text:'Aqui você acompanha os tickets da sua organização e os itens que precisam de atenção.' },
      { route:'dashboard', selector:'[data-action="open-new-ticket"]', title:'Abra uma solicitação', text:'Use este botão para abrir o painel lateral e registrar uma nova demanda sem sair do contexto.' },
      { route:'tickets', selector:'.view-toggle', title:'Kanban ou tabela', text:'Alterne entre o fluxo visual por status e a lista detalhada. Busca e filtros funcionam nas duas visões.' },
      { route:'tickets', selector:'.kanban-board', title:'Acompanhe o fluxo', text:'Selecione um cartão. Se ele estiver em validação, você será levado diretamente à decisão da entrega.' },
      { route:'notifications', selector:'.page-head', title:'Não perca atualizações', text:'Notificações reúnem pedidos de complemento, entregas para validar e mudanças importantes.' }
    ],
    'Atendimento': [
      { route:'dashboard', selector:'.metric-grid', title:'Visão da operação', text:'Os indicadores mostram volume ativo, prioridades, validações e dependências do cliente.' },
      { route:'tickets', selector:'.kanban-board', title:'Fila de trabalho', text:'O Kanban organiza todas as demandas da agência pelas etapas do processo.' },
      { route:'triage', selector:'[data-form="triage"]', title:'Triagem contextual', text:'Ao selecionar um ticket elegível, você chega direto à classificação, atribuição e regra de SLA.' },
      { route:'reports', selector:'.metric-grid', title:'Acompanhe resultados', text:'Use relatórios para observar volume, conclusão e cumprimento do SLA.' },
      { route:'campaigns', selector:'.entity-list', title:'Mantenha campanhas', text:'Cadastre e atualize as campanhas usadas na abertura e na triagem dos tickets.' }
    ],
    'Gestor de tráfego': [
      { route:'dashboard', selector:'.page-head', title:'Seu trabalho atribuído', text:'O painel e os contadores consideram apenas os tickets sob sua responsabilidade.' },
      { route:'tickets', selector:'.kanban-board', title:'Sua fila no Kanban', text:'Selecione um ticket em execução para abrir diretamente a área de entrega.' },
      { route:'execution', selector:'[data-form="execution"]', title:'Registre a execução', text:'Descreva o trabalho, anexe evidências e envie para validação ou conclua conforme o tipo.' },
      { route:'notifications', selector:'.page-head', title:'Acompanhe retornos', text:'Aqui aparecem novas atribuições, correções solicitadas e conclusões.' }
    ],
    'Administrador': [
      { route:'dashboard', selector:'.metric-grid', title:'Visão completa', text:'O painel resume a operação da agência e destaca os pontos que exigem atenção.' },
      { route:'tickets', selector:'.kanban-board', title:'Controle do fluxo', text:'No Kanban você acompanha todas as etapas e abre diretamente as ações permitidas para cada ticket.' },
      { route:'triage', selector:'[data-form="triage"]', title:'Continuidade da triagem', text:'O administrador pode classificar e atribuir tickets para garantir a continuidade operacional.' },
      { route:'clients', selector:'.entity-list', title:'Cadastros principais', text:'Clientes e campanhas alimentam os formulários e preservam os vínculos históricos.' },
      { route:'sla', selector:'.entity-list', title:'Regras de SLA', text:'Configure prazos e precedência por cliente, tipo ou regra padrão.' },
      { route:'users', selector:'.entity-list', title:'Acessos e perfis', text:'Gerencie usuários, papéis e vínculos respeitando a separação de responsabilidades.' }
    ]
  };

  function load() {
    try { const saved = localStorage.getItem(KEY); if (saved) return JSON.parse(saved); } catch (_) {}
    return C.clone(window.SIGE_SEED);
  }
  function persist() { localStorage.setItem(KEY, JSON.stringify(data)); }
  function user() { return C.byId(data.users, data.session); }
  function clientName(id) { return C.byId(data.clients, id)?.name || '—'; }
  function campaignName(id, pending) { return C.byId(data.campaigns, id)?.name || pending || 'Não informada'; }
  function typeName(id) { return C.byId(data.demandTypes, id)?.name || '—'; }
  function assigneeName(id) { return C.byId(data.users, id)?.name || 'Não atribuído'; }
  function ticketHref(ticket) {
    const role = user()?.role;
    if (['Atendimento','Administrador'].includes(role) && ['Aberta','Em triagem','Reaberta'].includes(ticket.status)) return `#triage/${ticket.id}`;
    if (role === 'Gestor de tráfego' && ['Em execução','Reaberta'].includes(ticket.status) && ticket.assigneeId === user().id) return `#execution/${ticket.id}`;
    if (role === 'Cliente' && ticket.status === 'Em validação' && ticket.clientId === user().clientId) return `#validation/${ticket.id}`;
    return `#ticket/${ticket.id}`;
  }
  function route() {
    const raw = location.hash.replace(/^#\/?/, '') || (data.session ? 'dashboard' : 'login');
    const [name, id] = raw.split('/');
    return { name, id };
  }
  function go(path) { location.hash = path; ui.mobile = false; }
  function statusBadge(status) { return `<span class="status s-${slug(status)}">${esc(status)}</span>`; }
  function screenHead(code, title, description, actions = '') {
    return `<header class="page-head"><div><span class="screen-code">${code}</span><h1>${title}</h1><p>${description}</p></div>${actions ? `<div class="row actions">${actions}</div>` : ''}</header>`;
  }
  function toast(message, kind = '') {
    const el = document.createElement('div'); el.className = `toast ${kind}`; el.textContent = message;
    $('#toast-region').append(el); setTimeout(() => el.remove(), 3200);
  }
  function navItems(currentUser) {
    return C.roleRoutes(currentUser.role).map(name => {
      const meta = C.ROUTES.find(r => r[0] === name); if (!meta) return '';
      return `<a href="#${name}" data-nav="${name}"><span class="nav-icon">${icon(name)}</span><span>${esc(meta[2])}</span></a>`;
    }).join('');
  }
  function shell(content, current) {
    const u = user();
    const unread = data.notifications.filter(n => n.userId === u.id && !n.read).length;
    return `<div class="app-shell">
      ${ui.mobile ? '<button class="mobile-overlay" data-action="close-menu" aria-label="Fechar menu"></button>' : ''}
      <aside class="sidebar ${ui.mobile ? 'open' : ''}"><div class="brand"><div class="brand-mark">SD</div><div><div class="brand-name">SIGE Desk</div><div class="brand-sub">Gestão de demandas</div></div></div>
        <nav class="nav" aria-label="Principal">${navItems(u)}</nav>
        <div class="sidebar-foot"><button class="tutorial-link" data-action="start-tutorial">? <span>Ver tutorial</span></button><div class="profile-mini"><div class="avatar">${initials(u.name)}</div><div><strong>${esc(u.name)}</strong><span>${esc(u.role)}</span></div><button class="icon-btn" data-action="logout" title="Sair" aria-label="Sair">↪</button></div></div>
      </aside><main class="main"><header class="topbar"><div class="row"><button class="icon-btn mobile-menu" data-action="open-menu" aria-label="Abrir menu">☰</button><span class="breadcrumb">SIGE Desk / <strong>${esc(current)}</strong></span></div><div class="top-actions"><span class="role-label small muted">Ambiente de demonstração</span><button class="icon-btn notif-button" data-action="notifications" aria-label="Notificações">🔔${unread ? '<span class="notif-dot"></span>' : ''}</button></div></header><div class="content">${content}</div></main></div>`;
  }
  function renderLogin() {
    const demos = [
      ['Cliente','cliente@aurora.demo','Acompanhar e validar entregas'],['Atendimento','atendimento@sige.demo','Triar e coordenar demandas'],
      ['Gestor de tráfego','gestor@sige.demo','Executar tickets atribuídos'],['Administrador','admin@sige.demo','Configurar e supervisionar']
    ];
    return `<main class="login-page"><section class="login-brand"><div><div class="brand"><div class="brand-mark">SD</div><div><div class="brand-name">SIGE Desk</div><div class="brand-sub">Protótipo acadêmico</div></div></div><h1>Demandas claras.<br>Operação sob controle.</h1><p>Um fluxo único para receber, priorizar, executar e validar solicitações de tráfego pago com histórico e SLA.</p></div><span class="small">PUC Minas · Sistemas de Gestão Integrados</span></section>
      <section class="login-panel"><div><span class="screen-code">T01</span><h2>Acessar o ambiente</h2><p class="muted">Use uma conta de demonstração ou preencha suas credenciais.</p></div>
      <form class="login-form" data-form="login" novalidate><div class="field"><label for="email">E-mail</label><input id="email" name="email" type="email" value="${esc(ui.loginEmail || '')}" autocomplete="username" placeholder="nome@empresa.com"><span class="field-error">${esc(ui.loginError)}</span></div><div class="field"><label for="password">Senha</label><input id="password" name="password" type="password" autocomplete="current-password" placeholder="••••••••"></div><button class="btn btn-primary" type="submit">Entrar no SIGE Desk</button></form>
      <div><p class="small muted">ACESSO RÁPIDO · SENHA DEMO123</p><div class="demo-grid">${demos.map(([role,email,desc])=>`<button class="demo-card" data-action="demo-login" data-email="${email}"><strong>${role}</strong><span>${desc}</span></button>`).join('')}</div></div><div class="auth-note row spread"><span>Dados simulados salvos apenas neste navegador.</span><button class="btn btn-ghost" data-action="reset-demo">Restaurar base</button></div></section></main>`;
  }
  function metric(label, value, foot, percent = 50) { return `<article class="card metric"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div><div class="metric-line"><span style="width:${percent}%"></span></div></article>`; }
  function renderDashboard() {
    const tickets = C.visibleTickets(data, user());
    const active = tickets.filter(t => !['Concluída','Cancelada'].includes(t.status));
    const urgent = active.filter(t => ['Urgente','Alta'].includes(t.priority || t.urgency));
    const validation = active.filter(t => t.status === 'Em validação');
    const waiting = active.filter(t => t.status === 'Aguardando cliente');
    const recent = tickets.slice().sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt)).slice(0,5);
    return `${screenHead('T02','Visão geral',`Acompanhe a operação disponível para o perfil ${esc(user().role)}.`, C.can(user(),'create')?'<button class="btn btn-primary" data-action="open-new-ticket">＋ Abrir ticket</button>':'')}
      <section class="metric-grid">${metric('Tickets ativos',active.length,'Em andamento agora',72)}${metric('Alta prioridade',urgent.length,'Urgentes ou altas',44)}${metric('Em validação',validation.length,'Aguardando decisão',28)}${metric('Aguardando cliente',waiting.length,'SLA pausado',34)}</section>
      <section class="two-col" style="margin-top:18px"><article class="card"><div class="section-head"><h2 class="section-title">Atividade recente</h2><a class="btn btn-ghost" href="#tickets">Ver todos →</a></div>${ticketTable(recent,true)}</article>
      <aside class="stack"><article class="card card-pad"><div class="row spread"><h2 class="section-title">Distribuição</h2><span class="small muted">por status</span></div><div class="donut" style="margin-top:18px"></div><div class="legend" style="margin-top:16px"><span style="--dot:#1378a7">Em triagem</span><span style="--dot:#0b826d">Em execução</span><span style="--dot:#e7a142">Aguardando cliente</span><span style="--dot:#c85d64">Demais estados</span></div></article><article class="card card-pad"><h2 class="section-title">Saúde do SLA</h2><p class="small muted">Tickets classificados da sua visão</p><div class="kpi-bar"><span class="bar-ok" style="width:62%">62%</span><span class="bar-risk" style="width:23%">23%</span><span class="bar-late" style="width:15%">15%</span></div></article></aside></section>`;
  }
  function ticketTable(items, compact = false) {
    if (!items.length) return `<div class="empty"><div class="empty-icon">⌕</div><h3>Nenhum ticket encontrado</h3><p>Ajuste os filtros ou crie uma nova solicitação.</p></div>`;
    return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Ticket</th><th>Cliente</th><th>Status</th><th>Prioridade</th>${compact?'':'<th>Responsável</th><th>Atualização</th>'}</tr></thead><tbody>${items.map(t=>`<tr><td><a class="ticket-link" href="${ticketHref(t)}">${esc(t.number)} · ${esc(t.subject)}</a><div class="small muted">${esc(typeName(t.typeId))}</div></td><td>${esc(clientName(t.clientId))}</td><td>${statusBadge(t.status)}</td><td><span class="priority p-${slug(t.priority||t.urgency)}">${esc(t.priority||t.urgency||'Pendente')}</span></td>${compact?'':`<td>${esc(assigneeName(t.assigneeId))}</td><td>${C.formatDate(t.updatedAt)}</td>`}</tr>`).join('')}</tbody></table></div>`;
  }
  function renderKanban(items) {
    return `<div class="kanban-board" aria-label="Quadro Kanban de tickets">${C.STATUS.map(status => {
      const tickets = items.filter(ticket => ticket.status === status);
      return `<section class="kanban-column" aria-labelledby="kanban-${slug(status)}">
        <header class="kanban-head"><div id="kanban-${slug(status)}">${statusBadge(status)}</div><span class="kanban-count" aria-label="${tickets.length} ticket(s)">${tickets.length}</span></header>
        <div class="kanban-stack">${tickets.length ? tickets.map(ticket => `<a class="kanban-card priority-border-${slug(ticket.priority || ticket.urgency)}" href="${ticketHref(ticket)}">
          <div class="row spread"><strong>${esc(ticket.number)}</strong><span class="priority p-${slug(ticket.priority || ticket.urgency)}">${esc(ticket.priority || ticket.urgency || 'Pendente')}</span></div>
          <h3>${esc(ticket.subject)}</h3>
          <p>${esc(clientName(ticket.clientId))}</p>
          <div class="kanban-meta"><span>${esc(campaignName(ticket.campaignId, ticket.pendingCampaign))}</span><span>${esc(assigneeName(ticket.assigneeId))}</span></div>
          <div class="row spread kanban-foot"><span>${esc(ticket.slaState)}</span><span>${C.formatDate(ticket.updatedAt)}</span></div>
        </a>`).join('') : '<div class="kanban-empty">Nenhum ticket</div>'}</div>
      </section>`;
    }).join('')}</div>`;
  }
  function renderTickets() {
    const visible = C.visibleTickets(data,user());
    const q = ui.search.toLowerCase();
    const items = visible.filter(t => (!q || `${t.number} ${t.subject} ${clientName(t.clientId)}`.toLowerCase().includes(q)) && (!ui.status || t.status === ui.status) && (!ui.client || t.clientId === ui.client));
    const toggle = `<div class="view-toggle" role="group" aria-label="Visualização dos tickets"><button class="view-option ${ui.ticketView==='kanban'?'active':''}" data-action="ticket-view" data-view="kanban" aria-pressed="${ui.ticketView==='kanban'}">▦ Kanban</button><button class="view-option ${ui.ticketView==='table'?'active':''}" data-action="ticket-view" data-view="table" aria-pressed="${ui.ticketView==='table'}">☷ Tabela</button></div>`;
    return `${screenHead('T03','Tickets','Acompanhe o fluxo no Kanban ou alterne para a visão em tabela.',`<button class="btn btn-secondary" data-action="export-csv">↓ Exportar CSV</button>${C.can(user(),'create')?'<button class="btn btn-primary" data-action="open-new-ticket">＋ Novo ticket</button>':''}`)}
      <section class="card tickets-panel">
        <div class="tickets-viewbar"><div><strong>${items.length} ticket(s)</strong><span class="small muted"> · ${ui.ticketView==='kanban'?'organizados por etapa':'lista detalhada'}</span></div>${toggle}</div>
        <div class="toolbar"><div class="field field-grow"><label for="ticket-search">Buscar</label><input id="ticket-search" data-filter="search" value="${esc(ui.search)}" placeholder="Número, assunto ou cliente"></div><div class="field"><label for="status-filter">Status</label><select id="status-filter" data-filter="status"><option value="">Todos</option>${C.STATUS.map(s=>`<option ${ui.status===s?'selected':''}>${s}</option>`).join('')}</select></div>${!['Cliente','Gestor de tráfego'].includes(user().role)?`<div class="field"><label for="client-filter">Cliente</label><select id="client-filter" data-filter="client"><option value="">Todos</option>${data.clients.map(c=>`<option value="${c.id}" ${ui.client===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>`:''}<button class="btn btn-secondary" data-action="clear-filters">Limpar</button></div>
        ${ui.ticketView === 'kanban' ? renderKanban(items) : ticketTable(items)}
      </section>`;
  }
  function renderNewTicket() {
    const u=user(), own=u.role==='Cliente';
    const availableClients=own?data.clients.filter(c=>c.id===u.clientId):data.clients.filter(c=>c.active);
    const clientId=ui.formClient||availableClients[0]?.id||'';
    const campaigns=data.campaigns.filter(c=>c.active&&c.clientId===clientId);
    return `${screenHead('T04','Novo ticket','Registre a solicitação com os dados necessários para uma triagem objetiva.','<button class="btn btn-secondary" data-action="cancel-new-ticket">Cancelar</button>')}
    <form class="stack" data-form="new-ticket" novalidate><section class="card card-pad"><div class="section-head" style="padding:0 0 16px;margin-bottom:18px"><h2 class="section-title">Identificação da demanda</h2><span class="small muted">* Campos obrigatórios</span></div><div class="form-grid">
      <div class="field"><label for="clientId">Cliente *</label><select id="clientId" name="clientId" data-form-client ${own?'disabled':''}>${availableClients.map(c=>`<option value="${c.id}" ${clientId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select>${own?`<input type="hidden" name="clientId" value="${clientId}">`:''}</div>
      <div class="field"><label for="typeId">Tipo de demanda *</label><select id="typeId" name="typeId"><option value="">Selecione</option>${data.demandTypes.filter(t=>t.active).map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select><span class="field-error">${esc(ui.fieldErrors.typeId||'')}</span></div>
      <div class="field full"><label for="subject">Assunto *</label><input id="subject" name="subject" maxlength="120" placeholder="Ex.: Ajustar orçamento da campanha de captação"><span class="field-error">${esc(ui.fieldErrors.subject||'')}</span></div>
      <div class="field"><label for="campaignId">Campanha</label><select id="campaignId" name="campaignId"><option value="">Selecione ou informe abaixo</option>${campaigns.map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.channel)}</option>`).join('')}</select></div>
      <div class="field"><label for="pendingCampaign">Campanha ainda não cadastrada</label><input id="pendingCampaign" name="pendingCampaign" placeholder="Nome provisório da campanha"></div>
      <div class="field"><label for="channel">Canal *</label><select id="channel" name="channel"><option value="">Selecione</option><option>Google Ads</option><option>Meta Ads</option><option>LinkedIn Ads</option><option>TikTok Ads</option><option>Outro</option></select><span class="field-error">${esc(ui.fieldErrors.channel||'')}</span></div>
      <div class="field"><label for="urgency">Urgência solicitada *</label><select id="urgency" name="urgency"><option>Média</option><option>Urgente</option><option>Alta</option><option>Baixa</option></select><span class="hint">A prioridade oficial será definida na triagem.</span></div>
      <div class="field"><label for="desiredDate">Data desejada</label><input id="desiredDate" name="desiredDate" type="date" min="2026-09-06"></div>
      <div class="field full"><label for="description">Descrição e resultado esperado *</label><textarea id="description" name="description" placeholder="Descreva o pedido, o contexto e como saberemos que foi concluído."></textarea><span class="field-error">${esc(ui.fieldErrors.description||'')}</span></div>
    </div></section><section class="card card-pad"><h2 class="section-title">Métricas e anexos</h2><p class="small muted">Campos opcionais que ajudam a contextualizar a decisão.</p><div class="form-grid"><div class="field"><label>Período analisado</label><input name="metricPeriod" placeholder="Ex.: 01/09 a 05/09/2026"></div><div class="field"><label>CTR (%)</label><input name="ctr" inputmode="decimal" placeholder="3,8"></div><div class="field"><label>CPA (R$)</label><input name="cpa" inputmode="decimal" placeholder="38,50"></div><div class="field"><label>ROAS</label><input name="roas" inputmode="decimal" placeholder="4,2"></div><div class="field full"><label for="files">Anexos</label><input id="files" name="files" type="file" multiple accept="image/*,.pdf,.csv,.xlsx"><span class="hint">Simulação: os nomes e tamanhos ficam registrados localmente.</span></div></div></section><div class="row spread"><span class="small muted">O SLA ficará pendente até a classificação.</span><button class="btn btn-primary" type="submit">Criar ticket</button></div></form>`;
  }
  function ticketForRoute() { return C.byId(C.visibleTickets(data,user()),route().id); }
  function statusProgress(ticket){const order=['Aberta','Em triagem','Em execução','Em validação','Concluída'];let at=order.indexOf(ticket.status);if(ticket.status==='Aguardando cliente')at=ticket.waitOrigin==='triagem'?1:2;if(ticket.status==='Reaberta')at=2;if(ticket.status==='Cancelada')at=0;return `<div class="progress" aria-label="Progresso do ticket">${order.map((s,i)=>`<span class="progress-step ${i<=at?'done':''}" title="${s}"></span>`).join('')}</div>`}
  function ticketActions(t){const buttons=[];if(C.can(user(),'triage',t))buttons.push(`<a class="btn btn-primary" href="#triage/${t.id}">Fazer triagem</a>`);if(C.can(user(),'execute',t))buttons.push(`<a class="btn btn-primary" href="#execution/${t.id}">Abrir execução</a>`);if(C.can(user(),'validate',t))buttons.push(`<a class="btn btn-accent" href="#validation/${t.id}">Validar entrega</a>`);if(C.can(user(),'complement',t))buttons.push(`<button class="btn btn-accent" data-action="send-complement" data-id="${t.id}">Enviar complemento</button>`);if(C.can(user(),'resume',t))buttons.push(`<button class="btn btn-primary" data-action="confirm-resume" data-id="${t.id}">Confirmar e retomar</button>`);if(C.can(user(),'reopen',t))buttons.push(`<button class="btn btn-secondary" data-action="open-reopen" data-id="${t.id}">Reabrir ticket</button>`);return buttons.join('')}
  function renderTicket() {
    const t=ticketForRoute(); if(!t)return renderNotFound('Ticket não encontrado','Ele não existe ou não está disponível para o seu perfil.');
    const sla=C.selectSla(data,t);return `${screenHead('T05',`${esc(t.number)} · ${esc(t.subject)}`,`${esc(clientName(t.clientId))} · aberto por ${esc(t.author)}`,`<a class="btn btn-secondary" href="#tickets">← Tickets</a>${ticketActions(t)}`)}
      <section class="card card-pad"><div class="row spread">${statusBadge(t.status)}<span class="small muted">Ciclo ${t.cycle} · atualizado ${C.formatDate(t.updatedAt)}</span></div>${statusProgress(t)}${t.status==='Aguardando cliente'?`<div class="alert alert-warning"><strong>Complemento solicitado:</strong><span>${esc(t.waitReason||'Informações adicionais necessárias.')}${t.complementReceived?' · Complemento recebido e aguardando confirmação.':''}</span></div>`:''}</section>
      <section class="detail-grid" style="margin-top:18px"><div class="stack"><article class="card card-pad"><h2 class="section-title">Dados da solicitação</h2><dl class="definition" style="margin-top:18px"><div><dt>Tipo</dt><dd>${esc(typeName(t.typeId))}</dd></div><div><dt>Campanha</dt><dd>${esc(campaignName(t.campaignId,t.pendingCampaign))}</dd></div><div><dt>Canal</dt><dd>${esc(t.channel)}</dd></div><div><dt>Prioridade</dt><dd class="priority p-${slug(t.priority||t.urgency)}">${esc(t.priority||'Pendente de triagem')}</dd></div><div><dt>Responsável</dt><dd>${esc(assigneeName(t.assigneeId))}</dd></div><div><dt>Data desejada</dt><dd>${C.formatDate(t.desiredDate)}</dd></div><div class="full"><dt>Descrição</dt><dd>${esc(t.description)}</dd></div></dl></article>
      ${Object.keys(t.metrics||{}).length?`<article class="card card-pad"><h2 class="section-title">Contexto de métricas</h2><dl class="definition" style="margin-top:18px">${Object.entries(t.metrics).filter(([,v])=>v).map(([k,v])=>`<div><dt>${esc(k.toUpperCase())}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl></article>`:''}
      <article class="card"><div class="section-head"><h2 class="section-title">Comentários</h2><span class="small muted">${t.comments.length} registro(s)</span></div><div class="card-pad">${t.comments.length?t.comments.map(c=>`<div class="comment"><div class="avatar">${initials(c.author)}</div><div><div class="row spread"><strong>${esc(c.author)}</strong><span class="small muted">${C.formatDate(c.at)}</span></div><p>${esc(c.text)}</p>${c.effectiveResponse?'<span class="screen-code">Resposta efetiva</span>':''}</div></div>`).join(''):'<p class="muted">Nenhum comentário ainda.</p>'}${C.can(user(),'comment',t)?`<form class="row" data-form="comment" data-id="${t.id}" style="margin-top:14px"><div class="field field-grow"><label for="commentText">Novo comentário</label><input id="commentText" name="text" placeholder="Escreva uma atualização objetiva" required></div><button class="btn btn-secondary" type="submit">Comentar</button></form>`:''}</div></article>
      <article class="card"><div class="section-head"><h2 class="section-title">Evidências e anexos</h2></div><div class="card-pad entity-list">${[...t.attachments,...t.evidence].length?[...t.attachments,...t.evidence].map(i=>`<div class="entity"><div><strong>${esc(i.name||i.description)}</strong><div class="small muted">${esc(i.nature||i.type||'Anexo')} · ${esc(i.author||'Solicitante')}</div></div><span class="screen-code">Arquivo simulado</span></div>`).join(''):'<p class="muted">Nenhuma evidência registrada.</p>'}</div></article></div>
      <aside class="stack"><article class="card card-pad"><h2 class="section-title">SLA</h2><dl class="definition" style="margin-top:16px"><div><dt>Estado</dt><dd>${esc(t.slaState)}</dd></div><div><dt>Regra aplicada</dt><dd>${esc(sla?.name||'Pendente')}</dd></div><div><dt>Primeira resposta</dt><dd>${C.formatDate(t.responseDue)}</dd></div><div><dt>Resolução</dt><dd>${C.formatDate(t.resolutionDue)}</dd></div></dl></article><article class="card"><div class="section-head"><h2 class="section-title">Histórico auditável</h2></div><div class="card-pad"><ol class="timeline">${t.history.map(h=>`<li><strong>${esc(h.action)}</strong><p>${esc(h.user)} · ${C.formatDate(h.at)}</p><p>${esc(h.from)} → ${esc(h.to)} · ${esc(h.reason)}</p></li>`).join('')}</ol></div></article></aside></section>`;
  }
  function renderTriage() {
    const r=route(),t=C.byId(data.tickets,r.id)||C.visibleTickets(data,user()).find(x=>['Aberta','Em triagem','Reaberta'].includes(x.status));if(!t)return renderNotFound('Nenhum ticket para triagem','Não há demanda elegível neste momento.');
    if(!C.can(user(),'triage',t))return renderNotFound('Triagem indisponível','O status atual não aceita classificação.');
    const sla=C.selectSla(data,t);return `${screenHead('T06',`Triagem · ${esc(t.number)}`,'Classifique, atribua e determine o fluxo de execução.',`<a class="btn btn-secondary" href="#ticket/${t.id}">Ver detalhes</a>`)}<form class="stack" data-form="triage" data-id="${t.id}"><section class="two-col"><article class="card card-pad"><h2 class="section-title">Classificação operacional</h2><div class="form-grid" style="margin-top:18px"><div class="field"><label>Prioridade *</label><select name="priority">${['Urgente','Alta','Média','Baixa'].map(v=>`<option ${v===(t.priority||t.urgency)?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Responsável *</label><select name="assigneeId">${data.users.filter(u=>u.role==='Gestor de tráfego'&&u.active).map(u=>`<option value="${u.id}" ${u.id===t.assigneeId?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div><div class="field"><label>Tipo confirmado</label><select name="typeId">${data.demandTypes.filter(x=>x.active).map(x=>`<option value="${x.id}" ${x.id===t.typeId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Campanha vinculada</label><select name="campaignId"><option value="">Pendente</option>${data.campaigns.filter(c=>c.clientId===t.clientId&&c.active).map(c=>`<option value="${c.id}" ${c.id===t.campaignId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field full"><label>Observação de triagem</label><textarea name="reason">Escopo revisado e pronto para execução.</textarea></div></div></article><aside class="stack"><article class="card card-pad"><h2 class="section-title">Regra de SLA aplicável</h2><p><strong>${esc(sla?.name||'Nenhuma regra ativa')}</strong></p><p class="small muted">Precedência: cliente + tipo, cliente, tipo e padrão.</p><div class="alert alert-info">A contagem parte da abertura do ticket e usa horário útil configurado.</div></article><article class="card card-pad"><h2 class="section-title">Ações alternativas</h2><div class="stack" style="margin-top:14px"><button type="button" class="btn btn-secondary" data-action="request-complement" data-id="${t.id}" data-origin="triagem">Solicitar complemento</button>${C.can(user(),'cancel',t)?`<button type="button" class="btn btn-danger" data-action="open-cancel" data-id="${t.id}">Cancelar antes da execução</button>`:''}</div></article></aside></section><div class="row spread"><a class="btn btn-secondary" href="#tickets">Voltar</a><button class="btn btn-primary" type="submit">Classificar e encaminhar</button></div></form>`;
  }
  function renderExecution() {
    const r=route(),eligible=C.visibleTickets(data,user()).filter(t=>['Em execução','Reaberta'].includes(t.status)),t=C.byId(eligible,r.id)||eligible[0];if(!t)return renderNotFound('Nenhum ticket em execução','As demandas atribuídas a você aparecerão aqui.');
    return `${screenHead('T07',`Execução · ${esc(t.number)}`,'Registre o trabalho realizado e a evidência antes de concluir.',`<a class="btn btn-secondary" href="#ticket/${t.id}">Ver ticket</a>`)}<form class="stack" data-form="execution" data-id="${t.id}"><section class="two-col"><article class="card card-pad"><h2 class="section-title">Entrega</h2><div class="field" style="margin-top:18px"><label>Resumo do que foi executado *</label><textarea name="description" placeholder="Descreva a alteração realizada, os parâmetros e o resultado."></textarea><span class="field-error">${esc(ui.fieldErrors.evidence||'')}</span></div><div class="field" style="margin-top:14px"><label>Link de evidência</label><input name="link" type="url" placeholder="https://... ou referência interna"></div><div class="field" style="margin-top:14px"><label>Anexo de evidência</label><input name="evidenceFile" type="file" accept="image/*,.pdf,.csv,.xlsx"></div></article><aside class="stack"><article class="card card-pad"><h2 class="section-title">Critérios do tipo</h2><p>${esc(typeName(t.typeId))}</p><div class="alert alert-info">${t.approvalRequired?'A entrega seguirá para validação do cliente.':'O tipo dispensa aprovação e será concluído automaticamente.'}</div><p class="small muted">Evidência: ${t.evidenceRequired?'obrigatória':'opcional'}.</p></article><article class="card card-pad"><h2 class="section-title">Dependência externa</h2><p class="small muted">Pause o SLA quando faltar informação do cliente.</p><button type="button" class="btn btn-secondary" data-action="request-complement" data-id="${t.id}" data-origin="execução">Solicitar complemento</button></article></aside></section><div class="row spread"><a class="btn btn-secondary" href="#tickets">Voltar</a><button class="btn btn-primary" type="submit">${t.approvalRequired?'Enviar para validação':'Concluir entrega'}</button></div></form>`;
  }
  function renderValidation() {
    const r=route(),eligible=C.visibleTickets(data,user()).filter(t=>t.status==='Em validação'),t=C.byId(eligible,r.id)||eligible[0];if(!t)return renderNotFound('Nenhuma entrega para validar','Quando o gestor enviar uma entrega, ela aparecerá aqui.');
    return `${screenHead('T08',`Validação · ${esc(t.number)}`,'Revise o material entregue e registre sua decisão.',`<a class="btn btn-secondary" href="#ticket/${t.id}">Ver histórico</a>`)}<section class="detail-grid"><div class="stack"><article class="card card-pad"><h2 class="section-title">Entrega submetida</h2><p>${esc(t.description)}</p><div class="entity-list">${t.evidence.map(i=>`<div class="entity"><div><strong>${esc(i.description)}</strong><div class="small muted">${esc(i.nature)} · ${esc(i.author)} · ${C.formatDate(i.at)}</div></div><button class="btn btn-secondary" data-action="preview-evidence">Visualizar</button></div>`).join('')}</div></article><article class="card card-pad"><h2 class="section-title">Sua decisão</h2><form class="stack" data-form="validation" data-id="${t.id}"><div class="field"><label>Observação</label><textarea name="note" placeholder="Registre um comentário para a agência."></textarea></div><div class="row"><button class="btn btn-accent" name="decision" value="approve">Aprovar e concluir</button><button class="btn btn-danger" name="decision" value="correct">Solicitar correção</button></div></form></article></div><aside class="card card-pad"><h2 class="section-title">O que acontece depois?</h2><ol class="timeline" style="margin-top:18px"><li><strong>Aprovação</strong><p>Conclui o ticket e preserva a decisão no histórico.</p></li><li><strong>Correção</strong><p>Retorna à execução com o mesmo responsável.</p></li><li><strong>Reabertura futura</strong><p>Após concluído, o cliente pode iniciar um novo ciclo.</p></li></ol></aside></section>`;
  }
  function renderNotifications() {
    const list=data.notifications.filter(n=>n.userId===user().id).sort((a,b)=>new Date(b.at)-new Date(a.at));return `${screenHead('T09','Notificações','Acompanhe eventos importantes dos seus tickets.',`<button class="btn btn-secondary" data-action="mark-all-read">Marcar todas como lidas</button>`)}<section class="card"><div class="tabs"><button class="tab ${ui.tab==='all'?'active':''}" data-action="notification-tab" data-tab="all">Todas</button><button class="tab ${ui.tab!=='all'?'active':''}" data-action="notification-tab" data-tab="unread">Não lidas</button></div><div class="card-pad entity-list">${list.filter(n=>ui.tab==='all'||!n.read).map(n=>`<button class="entity" style="width:100%;background:${n.read?'#fff':'#f2fafc'};text-align:left" data-action="open-notification" data-id="${n.id}"><div><div class="row"><strong>${esc(n.event)}</strong>${!n.read?'<span class="screen-code">Nova</span>':''}</div><p class="muted" style="margin:5px 0">${esc(n.summary)}</p><span class="small muted">${C.formatDate(n.at)}</span></div><span>→</span></button>`).join('')||'<div class="empty"><div class="empty-icon">✓</div><h3>Tudo em dia</h3><p>Não há notificações nesta visão.</p></div>'}</div></section>`;
  }
  function renderReports() {
    const tickets=C.visibleTickets(data,user()),total=tickets.length,done=tickets.filter(t=>t.status==='Concluída').length,classed=tickets.filter(t=>t.priority),within=classed.filter(t=>!['Atrasado','Violado'].includes(t.slaState)).length;return `${screenHead('T10','Relatórios','Analise volume, cumprimento de SLA e desempenho operacional.',`<button class="btn btn-secondary" data-action="export-csv">↓ Exportar dados</button>`)}<section class="toolbar card"><div class="field"><label>Período</label><select><option>Últimos 30 dias</option><option>Últimos 7 dias</option><option>Este trimestre</option></select></div><div class="field"><label>Cliente</label><select><option>Todos</option>${data.clients.map(c=>`<option>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Canal</label><select><option>Todos</option><option>Google Ads</option><option>Meta Ads</option><option>LinkedIn Ads</option></select></div></section><section class="metric-grid" style="margin-top:18px">${metric('Volume total',total,'tickets no período',68)}${metric('Concluídos',done,`${Math.round(done/Math.max(total,1)*100)}% do volume`,48)}${metric('SLA no prazo',`${Math.round(within/Math.max(classed.length,1)*100)}%`,'dos classificados',78)}${metric('Tempo médio','18h','até a resolução',55)}</section><section class="two-col" style="margin-top:18px"><article class="card"><div class="section-head"><h2 class="section-title">Volume por status</h2></div><div class="card-pad stack">${C.STATUS.map(s=>{const n=tickets.filter(t=>t.status===s).length;return `<div><div class="row spread"><span>${s}</span><strong>${n}</strong></div><div class="metric-line"><span style="width:${Math.max(4,n/Math.max(total,1)*100)}%"></span></div></div>`}).join('')}</div></article><aside class="card card-pad"><h2 class="section-title">Leitura rápida</h2><div class="donut" style="margin-top:24px"></div><p class="muted small" style="margin-top:20px">A amostra inclui os oito estados para demonstrar todos os filtros e cenários do protótipo.</p></aside></section>`;
  }
  function entityPage(code,title,description,kind,items,renderItem,canAdd=true){return `${screenHead(code,title,description,canAdd?`<button class="btn btn-primary" data-action="open-entity" data-kind="${kind}">＋ Adicionar</button>`:'')}<section class="card"><div class="toolbar"><div class="field field-grow"><label>Buscar</label><input data-filter="search" value="${esc(ui.search)}" placeholder="Filtrar registros"></div><button class="btn btn-secondary" data-action="clear-filters">Limpar</button></div><div class="card-pad entity-list">${items.filter(x=>JSON.stringify(x).toLowerCase().includes(ui.search.toLowerCase())).map(renderItem).join('')||'<div class="empty"><div class="empty-icon">⌕</div><h3>Nenhum registro</h3><p>Ajuste a busca ou adicione um novo item.</p></div>'}</div></section>`}
  function renderClients(){return entityPage('T11','Clientes','Cadastre organizações e controle sua disponibilidade para novas demandas.','client',data.clients,c=>`<div class="entity"><div><strong>${esc(c.name)}</strong><div class="small muted">${esc(c.contact)} · ${esc(c.email)} · ${esc(c.phone)}</div></div><div class="row"><span class="small ${c.active?'':'muted'}">${c.active?'Ativo':'Inativo'}</span><button class="toggle ${c.active?'on':''}" data-action="toggle-entity" data-kind="clients" data-id="${c.id}" aria-label="Alterar status"><span></span></button><button class="btn btn-secondary" data-action="open-entity" data-kind="client" data-id="${c.id}">Editar</button></div></div>`)}
  function renderCampaigns(){return entityPage('T12','Campanhas','Mantenha o catálogo usado na abertura e na triagem dos tickets.','campaign',data.campaigns,c=>`<div class="entity"><div><strong>${esc(c.name)}</strong><div class="small muted">${esc(clientName(c.clientId))} · ${esc(c.channel)} · ${esc(c.objective)}</div></div><div class="row"><span class="small">${c.active?'Ativa':'Inativa'}</span><button class="toggle ${c.active?'on':''}" data-action="toggle-entity" data-kind="campaigns" data-id="${c.id}"><span></span></button><button class="btn btn-secondary" data-action="open-entity" data-kind="campaign" data-id="${c.id}">Editar</button></div></div>`)}
  function renderTypes(){return entityPage('T13','Tipos de demanda','Defina campos, evidência e necessidade de aprovação por tipo.','type',data.demandTypes,t=>`<div class="entity"><div><strong>${esc(t.name)}</strong><div class="small muted">${t.fields.length} campo(s) · Aprovação ${t.approval?'obrigatória':'dispensada'} · Evidência ${t.evidence?'obrigatória':'opcional'}</div></div><div class="row"><button class="toggle ${t.active?'on':''}" data-action="toggle-entity" data-kind="demandTypes" data-id="${t.id}"><span></span></button><button class="btn btn-secondary" data-action="open-entity" data-kind="type" data-id="${t.id}">Editar</button></div></div>`)}
  function renderSla(){return entityPage('T14','Configuração de SLA','Configure calendários e prazos com precedência explícita.','sla',data.slaRules,r=>`<div class="entity"><div><div class="row"><strong>${esc(r.name)}</strong><span class="screen-code">${esc(r.scope)}</span></div><div class="small muted">${esc(r.schedule)} · ${esc(r.timezone)} · Urgente: ${r.deadlines.Urgente[0]}h/${r.deadlines.Urgente[1]}h</div></div><div class="row"><button class="toggle ${r.active?'on':''}" data-action="toggle-entity" data-kind="slaRules" data-id="${r.id}"><span></span></button><button class="btn btn-secondary" data-action="open-entity" data-kind="sla" data-id="${r.id}">Editar</button></div></div>`)}
  function renderUsers(){return entityPage('T15','Usuários e perfis','Administre acesso, vínculo com cliente e papel operacional.','user',data.users,u=>`<div class="entity"><div class="row"><div class="avatar">${initials(u.name)}</div><div><strong>${esc(u.name)}</strong><div class="small muted">${esc(u.email)} · ${esc(u.role)}${u.clientId?' · '+esc(clientName(u.clientId)):''}</div></div></div><div class="row"><span class="small">${u.active?'Ativo':'Inativo'}</span><button class="toggle ${u.active?'on':''}" data-action="toggle-entity" data-kind="users" data-id="${u.id}" ${u.id===user().id?'disabled':''}><span></span></button><button class="btn btn-secondary" data-action="open-entity" data-kind="user" data-id="${u.id}">Editar</button></div></div>`)}
  function renderNotFound(title,message){return `${screenHead('—',title,message)}<div class="card empty"><div class="empty-icon">!</div><h3>${esc(title)}</h3><p>${esc(message)}</p><a class="btn btn-secondary" href="#dashboard">Voltar ao painel</a></div>`}
  function render() {
    const r = route();
    if (!data.session || !user()?.active) { if (r.name !== 'login') history.replaceState(null,'','#login'); $('#app').innerHTML=renderLogin(); bindActive(); return; }
    if (r.name === 'login') { go('dashboard'); return; }
    const allowed = C.canAccessRoute(user().role,r.name);
    let content;
    if (!allowed) content = `${screenHead('403','Acesso restrito','Seu perfil não possui permissão para esta área.')}<div class="card empty"><div class="empty-icon">!</div><h3>Permissão necessária</h3><p>Use o menu para voltar a uma tela disponível.</p></div>`;
    else if (r.name === 'dashboard') content=renderDashboard();
    else if (r.name === 'tickets') content=renderTickets();
    else if (r.name === 'new-ticket') content=renderNewTicket();
    else if (r.name === 'ticket') content=renderTicket();
    else if (r.name === 'triage') content=renderTriage();
    else if (r.name === 'execution') content=renderExecution();
    else if (r.name === 'validation') content=renderValidation();
    else if (r.name === 'notifications') content=renderNotifications();
    else if (r.name === 'reports') content=renderReports();
    else if (r.name === 'clients') content=renderClients();
    else if (r.name === 'campaigns') content=renderCampaigns();
    else if (r.name === 'types') content=renderTypes();
    else if (r.name === 'sla') content=renderSla();
    else if (r.name === 'users') content=renderUsers();
    else content=renderNotFound('Página não encontrada','O endereço informado não corresponde a uma tela do protótipo.');
    $('#app').innerHTML=shell(content,(C.ROUTES.find(v=>v[0]===r.name)||['','','Página'])[2]); bindActive();
    if(ui.tour)setTimeout(showTourStep,0);else maybeOfferTutorial();
  }
  function bindActive(){ const r=route(); $$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===r.name)); }
  function login(email,password='demo123') {
    const found=data.users.find(u=>u.email.toLowerCase()===email.toLowerCase()&&u.password===password);
    if(!found){ui.loginError='E-mail ou senha inválidos.';ui.loginEmail=email;render();return}
    if(!found.active){ui.loginError='Esta conta está inativa.';ui.loginEmail=email;render();return}
    data.session=found.id;persist();ui.loginError='';ui.tourOffered=false;go('dashboard');toast(`Bem-vindo, ${found.name.split(' ')[0]}!`,'success');
  }
  function notifyTicket(ticket,event,summary,recipientId){data.notifications.unshift({id:`n-${Date.now()}`,userId:recipientId,ticketId:ticket.id,event,summary,at:new Date().toISOString(),read:false})}
  function modal(title,body,foot=''){ui.modal={title,body,foot};$('#modal-root').innerHTML=`<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" onclick="event.stopPropagation()"><header class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Fechar">✕</button></header><div class="modal-body">${body}</div>${foot?`<footer class="modal-foot">${foot}</footer>`:''}</section></div>`;$('#modal-root input, #modal-root textarea')?.focus()}
  function drawer(title,body,kind=''){ui.modal={title,body,kind};$('#modal-root').innerHTML=`<div class="drawer-backdrop" data-action="close-modal"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title" onclick="event.stopPropagation()"><header class="modal-head"><div><span class="screen-code">T04</span><h2 id="drawer-title">${esc(title)}</h2></div><button class="icon-btn" data-action="close-modal" aria-label="Fechar">✕</button></header><div class="drawer-body">${body}</div></section></div>`;$('#modal-root input, #modal-root textarea')?.focus()}
  function openNewTicketPanel(){drawer('Abrir novo ticket',renderNewTicket(),'new-ticket')}
  function closeModal(){ui.modal=null;$('#modal-root').innerHTML=''}
  function completedTours(){try{return JSON.parse(localStorage.getItem(TOUR_KEY)||'{}')}catch(_){return {}}}
  function clearTourTarget(){$$('.tour-target').forEach(element=>element.classList.remove('tour-target'))}
  function maybeOfferTutorial(){const u=user();if(!u||ui.tour||ui.tourOffered||completedTours()[u.id])return;ui.tourOffered=true;setTimeout(()=>startTutorial(),220)}
  function startTutorial(){const steps=TOUR_STEPS[user()?.role];if(!steps?.length)return;clearTourTarget();closeModal();ui.mobile=false;ui.tour={steps,index:0};render()}
  function showTourStep(){if(!ui.tour)return;const step=ui.tour.steps[ui.tour.index];if(!step)return finishTutorial(false);clearTourTarget();if(route().name!==step.route){go(step.route);return}setTimeout(()=>{if(!ui.tour)return;const current=ui.tour.steps[ui.tour.index];const target=$(current.selector)||$('.page-head')||$('.content');target?.scrollIntoView({block:'center',behavior:'smooth'});target?.classList.add('tour-target');const total=ui.tour.steps.length,index=ui.tour.index;$('#modal-root').innerHTML=`<div class="tour-backdrop" aria-hidden="true"></div><section class="tour-card" role="dialog" aria-modal="true" aria-labelledby="tour-title"><div class="row spread"><span class="screen-code">Tutorial · ${index+1} de ${total}</span><button class="tour-skip" data-action="tour-skip">Pular</button></div><h2 id="tour-title">${esc(current.title)}</h2><p>${esc(current.text)}</p><div class="tour-dots" aria-label="Progresso">${ui.tour.steps.map((_,i)=>`<span class="${i===index?'active':''}"></span>`).join('')}</div><div class="row spread"><button class="btn btn-secondary" data-action="tour-prev" ${index===0?'disabled':''}>← Anterior</button><button class="btn btn-primary" data-action="tour-next">${index===total-1?'Concluir':'Próximo →'}</button></div></section>`;$('.tour-card [data-action="tour-next"]')?.focus()},90)}
  function finishTutorial(skipped){const u=user(),done=completedTours();if(u){done[u.id]=true;localStorage.setItem(TOUR_KEY,JSON.stringify(done))}clearTourTarget();ui.tour=null;$('#modal-root').innerHTML='';if(route().name!=='dashboard')go('dashboard');else render();toast(skipped?'Tutorial encerrado. Você pode revê-lo pelo perfil.':'Tutorial concluído!','success')}
  function moveTutorial(direction){if(!ui.tour)return;const next=ui.tour.index+direction;if(next<0)return;if(next>=ui.tour.steps.length){finishTutorial(false);return}ui.tour.index=next;showTourStep()}
  function confirmModal(title,message,action,id,label='Confirmar',extra=''){modal(title,`<p>${esc(message)}</p>${extra}`,`<button class="btn btn-secondary" data-action="close-modal">Voltar</button><button class="btn btn-primary" data-action="${action}" data-id="${id}">${label}</button>`)}
  function now(){return new Date().toISOString()}
  function createTicket(form){const fd=new FormData(form),required=['typeId','subject','channel','description'];ui.fieldErrors={};required.forEach(k=>{if(!String(fd.get(k)||'').trim())ui.fieldErrors[k]='Campo obrigatório.'});if(Object.keys(ui.fieldErrors).length){if(ui.modal?.kind==='new-ticket')openNewTicketPanel();else render();toast('Revise os campos obrigatórios.','error');return}const type=C.byId(data.demandTypes,fd.get('typeId')),number=`SIGE-${data.meta.nextTicket++}`,id=`t-${number.split('-')[1]}`,files=[...form.querySelector('[name="files"]').files].map((f,i)=>({id:`at-${Date.now()}-${i}`,name:f.name,size:`${Math.max(1,Math.round(f.size/1024))} KB`,type:f.type||'arquivo',author:user().name}));const ticket={id,number,subject:fd.get('subject').trim(),clientId:fd.get('clientId'),campaignId:fd.get('campaignId')||null,pendingCampaign:fd.get('pendingCampaign').trim(),typeId:type.id,channel:fd.get('channel'),requester:user().name,author:user().name,urgency:fd.get('urgency'),desiredDate:fd.get('desiredDate'),priority:null,assigneeId:null,status:'Aberta',createdAt:now(),updatedAt:now(),responseDue:null,resolutionDue:null,slaState:'Pendente de classificação',waitOrigin:null,executionStarted:false,cycle:1,approvalRequired:type.approval,evidenceRequired:type.evidence,description:fd.get('description').trim(),metrics:{period:fd.get('metricPeriod'),ctr:fd.get('ctr'),cpa:fd.get('cpa'),roas:fd.get('roas')},comments:[],attachments:files,evidence:[],approval:null,history:[{at:now(),user:user().name,action:'Ticket criado',from:'—',to:'Aberta',reason:'Solicitação enviada pelo portal'}]};data.tickets.unshift(ticket);data.users.filter(u=>['Atendimento','Administrador'].includes(u.role)&&u.active).forEach(u=>notifyTicket(ticket,'Novo ticket',`${number} aguarda triagem.`,u.id));persist();ui.fieldErrors={};closeModal();go(`ticket/${id}`);toast(`${number} criado com sucesso.`,'success')}
  function submitTriage(form){const t=C.byId(data.tickets,form.dataset.id),fd=new FormData(form),type=C.byId(data.demandTypes,fd.get('typeId'));t.priority=fd.get('priority');t.assigneeId=fd.get('assigneeId');t.typeId=fd.get('typeId');t.campaignId=fd.get('campaignId')||null;t.approvalRequired=type.approval;t.evidenceRequired=type.evidence;if(t.status!=='Em triagem')C.transition(t,'Em triagem',user().name,'Triagem iniciada');C.transition(t,'Em execução',user().name,fd.get('reason'));const hours=C.selectSla(data,t)?.deadlines[t.priority]||[8,24];const base=new Date();t.responseDue=new Date(base.getTime()+hours[0]*3600000).toISOString();t.resolutionDue=new Date(base.getTime()+hours[1]*3600000).toISOString();t.slaState='No prazo';notifyTicket(t,'Ticket atribuído',`${t.number} foi atribuído a você.`,t.assigneeId);persist();go(`ticket/${t.id}`);toast('Triagem concluída e responsável notificado.','success')}
  function submitExecution(form){const t=C.byId(data.tickets,form.dataset.id),fd=new FormData(form),description=String(fd.get('description')||'').trim(),file=form.querySelector('[name="evidenceFile"]').files[0];if(t.evidenceRequired&&!description&&!fd.get('link')&&!file){ui.fieldErrors.evidence='Registre ao menos uma evidência.';render();return}t.evidence.unshift({id:`ev-${Date.now()}`,description:description||file?.name||'Evidência vinculada',link:fd.get('link')||'mock://arquivo',author:user().name,at:now(),nature:'Ação executada'});if(t.approvalRequired){C.transition(t,'Em validação',user().name,'Entrega enviada para decisão do cliente');const clientUser=data.users.find(u=>u.role==='Cliente'&&u.clientId===t.clientId&&u.active);if(clientUser)notifyTicket(t,'Em validação',`${t.number} está pronto para sua decisão.`,clientUser.id)}else{C.transition(t,'Concluída',user().name,'Conclusão automática conforme configuração do tipo');t.approval={decision:'Dispensa automática',user:'Configuração do tipo',at:now(),note:'Tipo sem aprovação obrigatória'};t.slaState='Cumprido'}persist();ui.fieldErrors={};go(`ticket/${t.id}`);toast(t.approvalRequired?'Entrega enviada para validação.':'Ticket concluído automaticamente.','success')}
  function submitValidation(form,submitter){const t=C.byId(data.tickets,form.dataset.id),fd=new FormData(form),decision=submitter?.value||fd.get('decision'),note=String(fd.get('note')||'').trim();if(decision==='approve'){C.transition(t,'Concluída',user().name,note||'Entrega aprovada pelo cliente');t.approval={decision:'Aprovado',user:user().name,at:now(),note:note||'Entrega validada'};t.slaState='Cumprido';toast('Entrega aprovada e ticket concluído.','success')}else{if(!note){toast('Informe o ajuste solicitado.','error');return}C.transition(t,'Em execução',user().name,note);t.approval={decision:'Correção solicitada',user:user().name,at:now(),note};notifyTicket(t,'Correção solicitada',`${t.number} retornou para execução.`,t.assigneeId);toast('Correção registrada e gestor notificado.','success')}persist();go(`ticket/${t.id}`)}
  function requestComplement(form){const t=C.byId(data.tickets,form.dataset.id),reason=new FormData(form).get('reason').trim();if(!reason)return;if(t.status==='Reaberta')C.transition(t,form.dataset.origin==='triagem'?'Em triagem':'Em execução',user().name,'Retomada do ciclo reaberto');C.transition(t,'Aguardando cliente',user().name,reason);t.waitOrigin=form.dataset.origin;t.waitReason=reason;t.complementReceived=false;t.slaState='Pausado';const recipient=data.users.find(u=>u.role==='Cliente'&&u.clientId===t.clientId&&u.active);if(recipient)notifyTicket(t,'Aguardando cliente',reason,recipient.id);persist();closeModal();go(`ticket/${t.id}`);toast('Complemento solicitado e SLA pausado.','success')}
  function sendComplement(form){const t=C.byId(data.tickets,form.dataset.id),fd=new FormData(form),text=fd.get('text').trim(),file=form.querySelector('[name="file"]').files[0];if(!text)return;t.comments.push({id:`cm-${Date.now()}`,author:user().name,at:now(),text,effectiveResponse:false});if(file)t.attachments.push({id:`at-${Date.now()}`,name:file.name,size:`${Math.max(1,Math.round(file.size/1024))} KB`,type:file.type||'arquivo',author:user().name});t.complementReceived=true;t.updatedAt=now();data.users.filter(u=>['Atendimento','Administrador'].includes(u.role)&&u.active).forEach(u=>notifyTicket(t,'Complemento recebido',`${t.number} aguarda conferência.`,u.id));persist();closeModal();render();toast('Complemento enviado para conferência.','success')}
  function resumeTicket(id){const t=C.byId(data.tickets,id),target=t.waitOrigin==='triagem'?'Em triagem':'Em execução';C.transition(t,target,user().name,'Complemento conferido e fluxo retomado');t.complementReceived=false;t.slaState='No prazo';persist();closeModal();go(target==='Em triagem'?`triage/${id}`:`ticket/${id}`);toast('Fluxo retomado.','success')}
  function cancelTicket(form){const t=C.byId(data.tickets,form.dataset.id),reason=new FormData(form).get('reason').trim();if(!reason)return;C.transition(t,'Cancelada',user().name,reason);t.cancelReason=reason;t.slaState='Encerrado por cancelamento';persist();closeModal();go(`ticket/${t.id}`);toast('Ticket cancelado.','success')}
  function reopenTicket(form){const t=C.byId(data.tickets,form.dataset.id),reason=new FormData(form).get('reason').trim();if(!reason)return;C.transition(t,'Reaberta',user().name,reason);t.cycle+=1;t.reopenOrigin='conclusão';t.slaState='Novo ciclo';t.approval=null;data.users.filter(u=>['Atendimento','Administrador'].includes(u.role)&&u.active).forEach(u=>notifyTicket(t,'Ticket reaberto',`${t.number} iniciou o ciclo ${t.cycle}.`,u.id));persist();closeModal();go(`ticket/${t.id}`);toast('Ticket reaberto em novo ciclo.','success')}
  function toggleEntity(kind,id){const item=C.byId(data[kind],id);if(!item)return;item.active=!item.active;persist();render();toast(`Registro ${item.active?'ativado':'inativado'}.`,'success')}
  function openEntity(kind,id){const map={client:['Cliente','clients'],campaign:['Campanha','campaigns'],type:['Tipo de demanda','demandTypes'],sla:['Regra de SLA','slaRules'],user:['Usuário','users']},[title,listKey]=map[kind],item=id?C.byId(data[listKey],id):null;let fields='';if(kind==='client')fields=`${inputField('Nome','name',item?.name,true)}${inputField('Contato','contact',item?.contact,true)}${inputField('E-mail','email',item?.email,true,'email')}${inputField('Telefone','phone',item?.phone)}`;if(kind==='campaign')fields=`<div class="field"><label>Cliente *</label><select name="clientId">${data.clients.filter(c=>c.active||c.id===item?.clientId).map(c=>`<option value="${c.id}" ${c.id===item?.clientId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>${inputField('Nome','name',item?.name,true)}${inputField('Canal','channel',item?.channel,true)}${inputField('Objetivo','objective',item?.objective,true)}`;if(kind==='type')fields=`${inputField('Nome','name',item?.name,true)}${inputField('Campos separados por vírgula','fields',item?.fields?.join(', '),true)}<label class="row"><input type="checkbox" name="approval" ${item?.approval?'checked':''}> Aprovação obrigatória</label><label class="row"><input type="checkbox" name="evidence" ${item?.evidence?'checked':''}> Evidência obrigatória</label>`;if(kind==='sla')fields=`${inputField('Nome','name',item?.name,true)}<div class="field"><label>Escopo *</label><select name="scope">${['Padrão','Cliente','Tipo','Cliente + tipo'].map(v=>`<option ${v===item?.scope?'selected':''}>${v}</option>`).join('')}</select></div>${inputField('Identificador do escopo','scopeId',item?.scopeId||'')}${inputField('Resposta urgente (h)','urgentResponse',item?.deadlines?.Urgente?.[0]||2,true,'number')}${inputField('Resolução urgente (h)','urgentResolution',item?.deadlines?.Urgente?.[1]||8,true,'number')}`;if(kind==='user')fields=`${inputField('Nome','name',item?.name,true)}${inputField('E-mail','email',item?.email,true,'email')}<div class="field"><label>Perfil *</label><select name="role">${['Cliente','Atendimento','Gestor de tráfego','Administrador'].map(v=>`<option ${v===item?.role?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Cliente vinculado</label><select name="clientId"><option value="">Sem vínculo</option>${data.clients.map(c=>`<option value="${c.id}" ${c.id===item?.clientId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>`;modal(`${item?'Editar':'Adicionar'} ${title.toLowerCase()}`,`<form class="stack" data-form="entity" data-kind="${kind}" data-id="${id||''}">${fields}<button class="btn btn-primary">Salvar alterações</button></form>`)}
  function inputField(label,name,value='',required=false,type='text'){return `<div class="field"><label>${label}${required?' *':''}</label><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></div>`}
  function saveEntity(form){const fd=new FormData(form),kind=form.dataset.kind,id=form.dataset.id,isNew=!id;let list,item;if(kind==='client'){list=data.clients;item=id?C.byId(list,id):{id:`c-${Date.now()}`,active:true};Object.assign(item,{name:fd.get('name'),contact:fd.get('contact'),email:fd.get('email'),phone:fd.get('phone')})}if(kind==='campaign'){list=data.campaigns;item=id?C.byId(list,id):{id:`cp-${Date.now()}`,active:true};Object.assign(item,{clientId:fd.get('clientId'),name:fd.get('name'),channel:fd.get('channel'),objective:fd.get('objective')})}if(kind==='type'){list=data.demandTypes;item=id?C.byId(list,id):{id:`tp-${Date.now()}`,active:true};Object.assign(item,{name:fd.get('name'),fields:fd.get('fields').split(',').map(v=>v.trim()).filter(Boolean),approval:fd.has('approval'),evidence:fd.has('evidence')})}if(kind==='sla'){list=data.slaRules;item=id?C.byId(list,id):{id:`sla-${Date.now()}`,active:true,timezone:'America/Sao_Paulo',schedule:'Seg–Sex, 08h–18h',holidays:'Nacionais',pauseValidation:false,deadlines:{Urgente:[2,8],Alta:[4,16],Média:[8,24],Baixa:[16,40]}};item.name=fd.get('name');item.scope=fd.get('scope');item.scopeId=fd.get('scopeId')||null;item.deadlines.Urgente=[Number(fd.get('urgentResponse')),Number(fd.get('urgentResolution'))]}if(kind==='user'){list=data.users;item=id?C.byId(list,id):{id:`u-${Date.now()}`,active:true,password:'demo123'};Object.assign(item,{name:fd.get('name'),email:fd.get('email'),role:fd.get('role'),clientId:fd.get('clientId')||null})}if(!item||!item.name){toast('Preencha os campos obrigatórios.','error');return}if(isNew)list.push(item);persist();closeModal();render();toast(`Registro ${isNew?'criado':'atualizado'} com sucesso.`,'success')}
  document.addEventListener('submit',e=>{const form=e.target,type=form.dataset.form;if(!type)return;e.preventDefault();if(type==='login'){const fd=new FormData(form);login(fd.get('email').trim(),fd.get('password'))}if(type==='new-ticket')createTicket(form);if(type==='comment'){const t=C.byId(data.tickets,form.dataset.id),text=new FormData(form).get('text').trim();if(text){t.comments.push({id:`cm-${Date.now()}`,author:user().name,at:now(),text,effectiveResponse:false});t.updatedAt=now();persist();render();toast('Comentário registrado.','success')}}if(type==='triage')submitTriage(form);if(type==='execution')submitExecution(form);if(type==='validation')submitValidation(form,e.submitter);if(type==='complement-request')requestComplement(form);if(type==='complement-send')sendComplement(form);if(type==='cancel')cancelTicket(form);if(type==='reopen')reopenTicket(form);if(type==='entity')saveEntity(form)});
  document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
    if(action==='demo-login')login(button.dataset.email);if(action==='reset-demo'){data=C.clone(window.SIGE_SEED);localStorage.removeItem(TOUR_KEY);persist();ui.loginError='';ui.loginEmail='';ui.tour=null;ui.tourOffered=false;go('login');render();toast('Base de demonstração restaurada.','success')}if(action==='start-tutorial')startTutorial();if(action==='tour-next')moveTutorial(1);if(action==='tour-prev')moveTutorial(-1);if(action==='tour-skip')finishTutorial(true);if(action==='logout'){clearTourTarget();ui.tour=null;$('#modal-root').innerHTML='';data.session=null;persist();go('login');render()}if(action==='notifications')go('notifications');if(action==='open-menu'){ui.mobile=true;render()}if(action==='close-menu'){ui.mobile=false;render()}if(action==='clear-filters'){ui.search='';ui.status='';ui.client='';render()}if(action==='ticket-view'){ui.ticketView=button.dataset.view;render()}if(action==='open-new-ticket')openNewTicketPanel();if(action==='cancel-new-ticket'){closeModal();if(route().name==='new-ticket')go('tickets')}if(action==='export-csv')exportCsv();if(action==='close-modal')closeModal();if(action==='request-complement')modal('Solicitar complemento',`<form data-form="complement-request" class="stack" data-id="${button.dataset.id}" data-origin="${button.dataset.origin}"><div class="field"><label>Informação necessária *</label><textarea name="reason" required placeholder="Explique objetivamente o que falta."></textarea></div><button class="btn btn-primary">Pausar e solicitar</button></form>`);if(action==='send-complement')modal('Enviar complemento',`<form data-form="complement-send" class="stack" data-id="${button.dataset.id}"><div class="field"><label>Complemento *</label><textarea name="text" required></textarea></div><div class="field"><label>Anexo opcional</label><input type="file" name="file"></div><button class="btn btn-primary">Enviar para conferência</button></form>`);if(action==='confirm-resume')confirmModal('Retomar execução','Confirma que o complemento recebido é suficiente?','resume-ticket',button.dataset.id,'Confirmar e retomar');if(action==='resume-ticket')resumeTicket(button.dataset.id);if(action==='open-cancel')modal('Cancelar ticket',`<form data-form="cancel" class="stack" data-id="${button.dataset.id}"><div class="alert alert-danger">O cancelamento encerra o fluxo antes da execução.</div><div class="field"><label>Motivo *</label><textarea name="reason" required></textarea></div><button class="btn btn-danger">Confirmar cancelamento</button></form>`);if(action==='open-reopen')modal('Reabrir ticket',`<form data-form="reopen" class="stack" data-id="${button.dataset.id}"><div class="field"><label>Motivo da reabertura *</label><textarea name="reason" required></textarea></div><button class="btn btn-primary">Iniciar novo ciclo</button></form>`);if(action==='preview-evidence')modal('Pré-visualização da evidência','<div class="empty"><div class="empty-icon">▧</div><h3>Material de demonstração</h3><p>Em produção, o arquivo ou link seria aberto nesta área.</p></div>','<button class="btn btn-secondary" data-action="close-modal">Fechar</button>');if(action==='mark-all-read'){data.notifications.filter(n=>n.userId===user().id).forEach(n=>n.read=true);persist();render();toast('Notificações marcadas como lidas.','success')}if(action==='notification-tab'){ui.tab=button.dataset.tab;render()}if(action==='open-notification'){const n=C.byId(data.notifications,button.dataset.id);n.read=true;persist();go(`ticket/${n.ticketId}`)}if(action==='toggle-entity')toggleEntity(button.dataset.kind,button.dataset.id);if(action==='open-entity')openEntity(button.dataset.kind,button.dataset.id);
  });
  document.addEventListener('input',e=>{if(e.target.dataset.filter==='search'){ui.search=e.target.value;render();$('#ticket-search')?.focus();}});
  document.addEventListener('change',e=>{if(e.target.dataset.filter){ui[e.target.dataset.filter]=e.target.value;render()}if(e.target.dataset.formClient!==undefined){ui.formClient=e.target.value;if(ui.modal?.kind==='new-ticket')openNewTicketPanel();else render()}});
  window.addEventListener('hashchange',render);
  function exportCsv(){const rows=C.visibleTickets(data,user()).map(t=>[t.number,t.subject,clientName(t.clientId),t.status,t.priority||t.urgency,assigneeName(t.assigneeId)]);const csv=['Número;Assunto;Cliente;Status;Prioridade;Responsável',...rows.map(r=>r.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(';'))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv'}));a.download='sige-desk-tickets.csv';a.click();URL.revokeObjectURL(a.href);toast('Relatório CSV gerado.','success')}
  function registerWebMcp(){const context=document.modelContext;if(!context?.registerTool)return;const tools=[{name:'list_visible_tickets',title:'Listar tickets visíveis',description:'Lista de forma resumida os tickets disponíveis para o perfil autenticado no protótipo.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return {profile:user()?.role||null,tickets:C.visibleTickets(data,user()).map(t=>({id:t.id,number:t.number,subject:t.subject,status:t.status,priority:t.priority||t.urgency}))}}},{name:'start_new_ticket',title:'Iniciar novo ticket',description:'Abre o painel de nova solicitação, se o perfil atual puder criar tickets.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(){if(!C.can(user(),'create'))throw new Error('O perfil atual não pode criar tickets.');openNewTicketPanel();return {screen:'T04',presentation:'panel',status:'ready'}}},{name:'create_demo_ticket',title:'Criar ticket de demonstração',description:'Cria um ticket na base local simulada e abre seu detalhe. Exige assunto, descrição, cliente, tipo e canal válidos.',inputSchema:{type:'object',properties:{subject:{type:'string',minLength:3},description:{type:'string',minLength:5},client_id:{type:'string'},type_id:{type:'string'},channel:{type:'string'},urgency:{type:'string',enum:['Urgente','Alta','Média','Baixa']}},required:['subject','description','client_id','type_id','channel'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!C.can(user(),'create'))throw new Error('O perfil atual não pode criar tickets.');if(!input||typeof input.subject!=='string'||input.subject.trim().length<3)throw new Error('Assunto inválido.');const client=C.byId(data.clients,input.client_id),type=C.byId(data.demandTypes,input.type_id);if(!client||!client.active||!type||!type.active)throw new Error('Cliente ou tipo inválido.');if(user().role==='Cliente'&&client.id!==user().clientId)throw new Error('O cliente só pode criar tickets para a própria organização.');const number=`SIGE-${data.meta.nextTicket++}`,id=`t-${number.split('-')[1]}`,created=now();const ticket={id,number,subject:input.subject.trim(),clientId:client.id,campaignId:null,pendingCampaign:'',typeId:type.id,channel:input.channel,requester:user().name,author:user().name,urgency:input.urgency||'Média',desiredDate:'',priority:null,assigneeId:null,status:'Aberta',createdAt:created,updatedAt:created,responseDue:null,resolutionDue:null,slaState:'Pendente de classificação',waitOrigin:null,executionStarted:false,cycle:1,approvalRequired:type.approval,evidenceRequired:type.evidence,description:input.description.trim(),metrics:{},comments:[],attachments:[],evidence:[],approval:null,history:[{at:created,user:user().name,action:'Ticket criado',from:'—',to:'Aberta',reason:'Solicitação criada pela ferramenta do protótipo'}]};data.tickets.unshift(ticket);persist();go(`ticket/${id}`);return {id,number,status:'Aberta'}}}];tools.forEach(tool=>{try{void Promise.resolve(context.registerTool(tool)).catch(()=>{})}catch(_){}})}
  registerWebMcp();
  render();
})();
